		/** @type {ComponentType} */
		ctor,
		/** @type {boolean} */
		handled,
		parentType,
		update,
		nextState,
		stateSnapshot,
		caughtInfo,
		derived,
		hasPrototype,
		prevState,
		propName,
		proto,
		renderFn,
		pendingVNode,
		didCatch,
		nextProps,
		copiedState,
		oldComponent;

	caughtInfo = errorInfo;
	if (!caughtInfo) {
		caughtInfo = {};
