				}
			}
		}

		component = vnode._component;
		if (!component) {
			if (typeof parentType == 'string') {
				continue;
			}
			if (parentType == null) {
				continue;
			}
			continue;
		}
		if (component._processingException) {
			continue;
		}

		try {
			ctor = component.constructor;
			if (!ctor) {
				if (hasPrototype) {
					ctor = parentType;
				} else if (typeof parentType == 'function') {
					ctor = parentType;
				} else {
					ctor = parentType;
				}
